import React, { useState, useEffect } from 'react';
import { motion, useScroll, useTransform, AnimatePresence } from 'framer-motion';
import { SLIDES, CONTACT } from '../constants';
import { ChevronRight } from 'lucide-react';

const Hero: React.FC = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const { scrollY } = useScroll();
  const yBg = useTransform(scrollY, [0, 800], [0, 250]);
  const opacityText = useTransform(scrollY, [0, 400], [1, 0]);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % SLIDES.length);
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  return (
    <section className="relative h-screen w-full overflow-hidden bg-racing-black">
      {/* Parallax Background */}
      <motion.div 
        style={{ y: yBg }}
        className="absolute inset-0 w-full h-full"
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={currentSlide}
            initial={{ opacity: 0, scale: 1.1 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.5, ease: "easeOut" }}
            className="absolute inset-0 bg-cover bg-center"
            style={{ backgroundImage: `url(${SLIDES[currentSlide].image})` }}
          >
            <div className="absolute inset-0 bg-gradient-to-b from-racing-black/40 via-racing-black/20 to-racing-black" />
          </motion.div>
        </AnimatePresence>
      </motion.div>

      {/* Decorative Texture */}
      <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] pointer-events-none" />

      {/* Content */}
      <motion.div 
        style={{ opacity: opacityText }}
        className="relative z-10 h-full flex flex-col items-center justify-center text-center px-6"
      >
        <motion.div
          key={`sub-${currentSlide}`}
          initial={{ opacity: 0, letterSpacing: "0.2em" }}
          animate={{ opacity: 1, letterSpacing: "0.5em" }}
          transition={{ duration: 1 }}
          className="text-racing-red font-bold text-xs md:text-sm uppercase mb-6 tracking-[0.5em]"
        >
          {SLIDES[currentSlide].subtitle}
        </motion.div>

        <motion.h1
          key={`title-${currentSlide}`}
          initial={{ y: 50, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          className="font-display font-black text-6xl md:text-8xl lg:text-9xl italic text-white leading-none uppercase mb-12 text-glow-red"
        >
          {SLIDES[currentSlide].title.split(' ').map((word, i) => (
            <span key={i} className="block">{word}</span>
          ))}
        </motion.h1>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.6 }}
          className="flex flex-col md:flex-row gap-4"
        >
          <a
            href={CONTACT.whatsappLink}
            target="_blank"
            rel="noopener noreferrer"
            className="group relative inline-flex items-center gap-3 px-10 py-5 bg-racing-red text-white font-black uppercase tracking-widest overflow-hidden hover:bg-red-700 transition-all rounded-full shadow-[0_10px_30px_rgba(214,0,0,0.4)] hover:shadow-[0_15px_40px_rgba(214,0,0,0.6)]"
          >
            <span>Solicitar Orçamento</span>
            <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
          </a>

          <a
            href="#servicos"
            className="px-10 py-5 border border-white/20 text-white font-bold uppercase tracking-widest rounded-full hover:bg-white/10 transition-all"
          >
            Nossos Serviços
          </a>
        </motion.div>
      </motion.div>

      {/* Hero Bottom Gradient */}
      <div className="absolute bottom-0 left-0 w-full h-40 bg-gradient-to-t from-racing-black to-transparent pointer-events-none" />
    </section>
  );
};

export default Hero;

