const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };

    const checkStatus = () => {
      const now = new Date();
      const day = now.getDay(); // 0 Dom, 1-5 Seg-Sex, 6 Sab
      const hours = now.getHours();
      const minutes = now.getMinutes();
      const currentTime = hours + minutes / 60;

      let open = false;
      if (day >= 1 && day <= 5) { // Segunda a Sexta: 08:00 – 18:00
        open = currentTime >= 8 && currentTime < 18;
      } else if (day === 6) { // Sábado: 08:00 – 12:00
        open = currentTime >= 8 && currentTime < 12;
      }
      setIsOpen(open);
    };

    checkStatus();
    const statusInterval = setInterval(checkStatus, 60000);
    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearInterval(statusInterval);
    };
  }, []);

  const handleNavClick = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    if (id === 'top') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <motion.nav
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 ${
        isScrolled 
          ? 'bg-black/95 backdrop-blur-2xl py-3 border-b border-white/10 shadow-2xl' 
          : 'bg-transparent py-6 md:py-8'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 md:px-6 flex justify-between items-center">
        {/* Logo Section */}
        <a 
          href="/" 
          onClick={(e) => handleNavClick(e, 'top')}
          className="flex items-center gap-3 md:gap-4 group relative z-10 cursor-pointer"
        >
          <div className="relative p-1 bg-black rounded-full border border-white/10 group-hover:border-racing-red transition-all shadow-[0_0_20px_rgba(0,0,0,1)] shrink-0">
            <img 
              src={LOGO_URL} 
              alt="Franco Auto Center Logo" 
              className="w-10 h-10 md:w-14 md:h-14 rounded-full object-cover transition-all group-hover:scale-105"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://via.placeholder.com/150/D60000/FFFFFF?text=FRANCO';
              }}
            />
          </div>
          <div className="flex flex-col">
            <span className="text-white font-display font-black text-xl md:text-3xl uppercase tracking-[0.12em] scale-x-110 origin-left leading-none">
              Franco
            </span>
            <span className="text-white font-display font-bold text-[7px] md:text-[9px] uppercase tracking-[0.45em] mt-1 leading-none opacity-80">
              Auto Center
            </span>

            {/* Status do Estabelecimento */}
            <div className="flex items-center gap-1.5 mt-2.5">
              <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isOpen ? 'bg-green-500 shadow-[0_0_8px_#22c55e]' : 'bg-racing-red shadow-[0_0_8px_#D60000]'}`}></div>
              <span className={`text-[8px] md:text-[10px] font-black uppercase tracking-[0.2em] italic ${isOpen ? 'text-green-400' : 'text-racing-red'}`}>
                {isOpen ? 'Aberto Agora' : 'Fechado'}
              </span>
            </div>
          </div>
        </a>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center gap-10 relative z-10">
           {['Início', 'Serviços', 'Contato'].map((item) => (
             <a 
               key={item}
               href={`#${item.toLowerCase().replace('í', 'i')}`}
               onClick={(e) => handleNavClick(e, item === 'Início' ? 'top' : item.toLowerCase().replace('í', 'i'))}
               className="text-white/60 hover:text-white text-[11px] font-black uppercase tracking-[0.3em] transition-all relative group cursor-pointer"
             >
               {item}
               <span className="absolute -bottom-1 left-0 w-0 h-px bg-racing-red transition-all group-hover:w-full"></span>
             </a>
           ))}

           <motion.a
            whileHover={{ scale: 1.05, backgroundColor: '#D60000', color: '#FFFFFF' }}
            whileTap={{ scale: 0.95 }}
            href={CONTACT.whatsappLink}
            target="_blank"
            rel="noopener noreferrer"
            className="bg-white text-black font-black text-[11px] px-8 py-4 uppercase tracking-[0.2em] rounded-full transition-all shadow-[0_10px_30px_rgba(255,255,255,0.1)] hover:shadow-racing-red/40 cursor-pointer flex items-center gap-3"
          >
            Falar com Especialista
            <MessageCircle className="w-4 h-4" />
          </motion.a>
        </div>

        {/* Mobile Button */}
        <div className="md:hidden flex items-center ml-2">
          <motion.a
            whileTap={{ scale: 0.9 }}
            href={CONTACT.whatsappLink}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2 bg-racing-red text-white px-4 py-2.5 rounded-full shadow-[0_8px_20px_rgba(214,0,0,0.4)] relative z-10 cursor-pointer text-[9px] font-black uppercase tracking-wider whitespace-nowrap"
          >
            <MessageCircle className="w-3.5 h-3.5 fill-white" />
            <span>Especialista</span>
          </motion.a>
