                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-4 border-racing-metal ${isOpen ? 'bg-green-500' : 'bg-racing-red'} animate-pulse`}></div>
                </div>
                <div>
                  <h4 className="text-white font-display font-black text-sm uppercase italic tracking-wider leading-none mb-1">Assistência Técnica</h4>
                  <div className="flex items-center gap-1.5">
                    <ShieldCheck className="w-3 h-3 text-racing-red" />
                    <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">Especialista Franco</p>
                  </div>
                </div>
              </div>

              <div className="space-y-4 mb-8">
                <div className="bg-white/5 rounded-2xl p-4 border border-white/5">
                  <p className="text-gray-200 text-xs leading-relaxed font-medium">
                    "Pronto para agendar sua revisão? Clique abaixo e fale diretamente com nossa equipe técnica."
                  </p>
                </div>
                <div className="flex items-center justify-between px-1">
                  <div className="flex items-center gap-2">
                    <Zap className="w-3 h-3 text-yellow-500 fill-yellow-500" />
                    <span className="text-[9px] text-gray-500 font-black uppercase tracking-widest">Resposta em 5 min</span>
                  </div>
                  <span className="text-[9px] text-racing-red font-black uppercase tracking-widest animate-pulse">Live</span>
                </div>
              </div>

              <motion.a 
                href={CONTACT.whatsappLink}
                target="_blank"
                rel="noopener noreferrer"
                whileHover={{ scale: 1.02, backgroundColor: '#D60000' }}
                whileTap={{ scale: 0.98 }}
                className="flex items-center justify-center gap-3 bg-white text-black py-5 rounded-2xl text-[11px] font-black uppercase tracking-[0.2em] transition-all shadow-xl cursor-pointer group"
              >
                <MessageCircle className="w-5 h-5 fill-current" />
                Agendar via WhatsApp
              </motion.a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Gatilho de Backup (Flutuante) */}
      <motion.button
        onClick={() => setShowBubble(prev => !prev)}
        initial={{ opacity: 0, scale: 0.5 }}
        animate={{ opacity: 1, scale: 1 }}
        whileHover={{ scale: 1.1, rotate: 5 }}
        className="pointer-events-auto w-16 h-16 bg-racing-red text-white rounded-[1.5rem] flex items-center justify-center shadow-[0_15px_40px_rgba(214,0,0,0.4)] border border-white/20 cursor-pointer relative overflow-hidden group"
      >
        <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
        <MessageCircle className="w-8 h-8 relative z-10" />
      </motion.button>
    </div>
  );
};

export default WhatsAppButton;
